[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$hdr = @{ 'User-Agent' = 'claude-code' }
Write-Output "=== LATEST release assets ==="
$rel = Invoke-RestMethod 'https://api.github.com/repos/matlab/matlab-agentic-toolkit/releases/latest' -Headers $hdr
"tag: $($rel.tag_name)"
$rel.assets | ForEach-Object { "{0}  ({1:N2} MB)" -f $_.name, ($_.size/1MB) }
Write-Output "=== ALL releases (tag / #assets) ==="
$all = Invoke-RestMethod 'https://api.github.com/repos/matlab/matlab-agentic-toolkit/releases' -Headers $hdr
$all | ForEach-Object { "{0}  assets={1}  prerelease={2}" -f $_.tag_name, $_.assets.Count, $_.prerelease }

[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$hdr = @{ 'User-Agent' = 'claude-code' }
$base = 'https://raw.githubusercontent.com/matlab/matlab-agentic-toolkit/main/'
$tmp = Join-Path $env:TEMP 'mat-atk'
New-Item -ItemType Directory -Force -Path $tmp | Out-Null
foreach ($f in @('README.md','Configuration_and_Troubleshooting.md')) {
  Invoke-WebRequest ($base + $f) -OutFile (Join-Path $tmp ($f -replace '/','_')) -Headers $hdr
}
Write-Output "=== .claude-plugin tree ==="
$tree = Invoke-RestMethod 'https://api.github.com/repos/matlab/matlab-agentic-toolkit/git/trees/main?recursive=1' -Headers $hdr
$tree.tree | Where-Object { $_.path -like '.claude-plugin*' -or $_.path -like '.agents*' } | ForEach-Object { $_.path }
Write-Output "=== skills-catalog top level ==="
$tree.tree | Where-Object { $_.path -match '^skills-catalog/[^/]+$' } | ForEach-Object { $_.path }
"SAVED TO: $tmp"

foreach ($g in @('matlab-core','signal-processing','wireless-communications')) {
  Write-Output "===== installing $g ====="
  & claude plugin install "$g@matlab-agentic-toolkit" --scope user
}
Write-Output "===== claude plugin list ====="
& claude plugin list

input.content:
% sine_demo.m
% Generate and visualize a sine wave, then save the figure as a PNG.

f  = 5;              % Signal frequency (Hz)
fs = 1000;           % Sampling frequency (Hz)
T  = 1;              % Duration (s)
t  = 0:1/fs:T;       % Time vector
y  = sin(2*pi*f*t);  % Sine wave

fig = figure('Color', 'w');
plot(t, y, 'LineWidth', 1.5, 'Color', [0 0.447 0.741]);
grid on;
xlabel('Time (s)');
ylabel('Amplitude');
title(sprintf('Sine Wave — %d Hz, f_s = %d Hz', f, fs));
ylim([-1.2 1.2]);

scriptDir = fileparts(mfilename('fullpath'));
outFile = fullfile(scriptDir, 'sine_demo.png');
exportgraphics(fig, outFile, 'Resolution', 150);

fprintf('Generated %d samples over %g s.\n', numel(t), T);
fprintf('Peak amplitude = %.3f, RMS = %.3f\n', max(y), rms(y));
fprintf('Saved figure to: %s\n', outFile);

