input.command:
$home_ = 'C:\Users\CWH'
Write-Output "===== 1) Claude 主配置 (~/.claude.json) 里的 matlab MCP 条目 ====="
$cfg = Get-Content "$home_\.claude.json" -Raw | ConvertFrom-Json
$cfg.mcpServers.matlab | ConvertTo-Json -Depth 5
Write-Output ""
Write-Output "===== 2) ~/.claude 目录结构(找插件/市场配置) ====="
Get-ChildItem "$home_\.claude" -Force | Select-Object Mode, Name | Format-Table -AutoSize | Out-String
Write-Output "===== 3) 插件/市场存放目录 ~/.claude/plugins ====="
if (Test-Path "$home_\.claude\plugins") {
  Get-ChildItem "$home_\.claude\plugins" -Recurse -Depth 2 -Force | Select-Object FullName | Format-Table -AutoSize | Out-String
} else { "（无 plugins 目录）" }
Write-Output "===== 4) 用户 settings.json 是否含插件/市场声明 ====="
if (Test-Path "$home_\.claude\settings.json") {
  "$home_\.claude\settings.json 存在:"
  Get-Content "$home_\.claude\settings.json" -Raw
} else { "（无 ~/.claude/settings.json）" }
Write-Output "===== 5) MCP server 二进制与配套工具箱 ====="
Get-ChildItem "$home_\.matlab\agentic-toolkits" -Recurse -File -Force | Select-Object FullName, @{n='MB';e={[math]::Round($_.Length/1MB,2)}} | Format-Table -AutoSize | Out-String
